    assert proteins("AUGUUUUCU") == "MethioninePhenylalanineSerine"


def test_ac3_codon_translates_to_amino_acid():
    assert proteins("AUGUUUUCU") == "MethioninePhenylalanineSerine"


def test_ac4_amino_acids_join_to_protein():
    assert proteins("AUGUUUUCU") == "MethioninePhenylalanineSerine"


def test_ac5_real_world_64_codons_20_amino_acids():
    assert proteins("AUGUUUUCU") == "MethioninePhenylalanineSerine"


def test_ac6_exercise_uses_fewer_codons():
    assert proteins("AUGUUUUCU") == "MethioninePhenylalanineSerine"


def test_ac7_codon_to_amino_acid_mapping():
